css:
/* Layout: one reading column (~70ch) with wide code, tables and the entry strips allowed to scroll in their own boxes. */
:root{
  --bg:#f6f7f9; --panel:#ffffff; --fg:#1c2330; --muted:#5b6474; --rule:#d9dde4; --code:#eef1f5;
  --accent:#1f5f8b; --accent-soft:#dbe8f2; --bad:#b4372f; --bad-soft:#f6dedb; --good:#2f7a4d; --good-soft:#dcefe3;
  --bk0:#cfe3f5; --bk1:#d9ecd3; --bk2:#f6e7c8; --bk3:#e7dbf3; --refc:#b4372f; --collc:#e9a59f;
  --display:"IBM Plex Sans Condensed","Arial Narrow",sans-serif;
  --body:"Source Sans 3","Segoe UI",system-ui,sans-serif;
  --mono:"JetBrains Mono",ui-monospace,Menlo,Consolas,monospace;
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
  --bg:#12161d; --panel:#1a2029; --fg:#e3e7ee; --muted:#9aa4b3; --rule:#2c3440; --code:#202833;
  --accent:#7db5dc; --accent-soft:#1f3546; --bk0:#1f3a52; --bk1:#24402a; --bk2:#4a3b1c; --bk3:#3a2d4d; --refc:#ff8a80; --collc:#7a2f2a; --bad:#ec8a80; --bad-soft:#41231f; --good:#7fcf9c; --good-soft:#1d3527; color-scheme:dark}}
:root[data-theme="dark"]{
  --bg:#12161d; --panel:#1a2029; --fg:#e3e7ee; --muted:#9aa4b3; --rule:#2c3440; --code:#202833;
  --accent:#7db5dc; --accent-soft:#1f3546; --bk0:#1f3a52; --bk1:#24402a; --bk2:#4a3b1c; --bk3:#3a2d4d; --refc:#ff8a80; --collc:#7a2f2a; --bad:#ec8a80; --bad-soft:#41231f; --good:#7fcf9c; --good-soft:#1d3527; color-scheme:dark}
body{background:var(--bg);color:var(--fg);font:clamp(16px,.5vw + 13px,21px)/1.6 var(--body)}
.wrap{width:100%;max-width:min(100%,1680px);box-sizing:border-box;margin:0 auto;padding-inline:clamp(16px,4vw,64px);padding-block:40px 80px;display:flex;flex-direction:column;gap:40px}
header{display:flex;flex-direction:column;gap:10px}
.eyebrow{font:600 12px/1 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}
h1{font:600 clamp(30px,5vw,42px)/1.1 var(--display);margin:0;text-wrap:balance}
h2{font:600 26px/1.2 var(--display);margin:0;text-wrap:balance}
h3{font:600 19px/1.3 var(--display);margin:8px 0 0}
p,ul,ol{margin:0}
section>p,section>ul,section>ol,header>p,.callout>p,.callout>ul,.callout>ol{max-width:90ch}
section{display:flex;flex-direction:column;gap:14px;min-width:0}
ul,ol{padding-left:1.3em;display:flex;flex-direction:column;gap:6px}
code{font:13.5px var(--mono);background:var(--code);padding:1px 5px;border-radius:3px}
pre{margin:0;padding:14px 16px;background:var(--code);border-radius:5px;overflow-x:auto;font:13px/1.55 var(--mono);white-space:pre}
pre .c{color:var(--muted)} pre .hl{background:var(--bad-soft);color:var(--bad);font-weight:600} pre .ok{color:var(--good);font-weight:600}
.lede{font-size:19px;color:var(--fg)}
.small{font-size:14.5px;color:var(--muted)}
.tw{overflow-x:auto;border:1px solid var(--rule);border-radius:5px;background:var(--panel)}
table{border-collapse:collapse;width:100%;font-size:15px}
th,td{padding:8px 12px;border-bottom:1px solid var(--rule);text-align:left;vertical-align:top}
tr:last-child td{border-bottom:0}
th{font:600 12px/1.3 var(--mono);letter-spacing:.04em;text-transform:uppercase;color:var(--muted);background:var(--code)}
td.n,th.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
td.m{font-family:var(--mono);font-size:13.5px;white-space:nowrap}
.tag{display:inline-block;font:600 11.5px/1 var(--mono);padding:4px 7px;border-radius:3px;letter-spacing:.03em;white-space:nowrap}
.t-bad{background:var(--bad-soft);color:var(--bad)} .t-good{background:var(--good-soft);color:var(--good)} .t-info{background:var(--accent-soft);color:var(--accent)}
.callout{border:1px solid var(--rule);background:var(--panel);border-radius:6px;padding:16px 18px;display:flex;flex-direction:column;gap:8px}
/* entry strips */
.strips{display:grid;grid-template-columns:1fr;gap:18px}
.strip{display:flex;flex-direction:column;gap:8px;min-width:0}
.strip .head{display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-weight:600}
.cells{display:grid;grid-template-columns:repeat(16,minmax(30px,1fr));gap:3px;overflow-x:auto}
.cell{border:1px solid var(--rule);border-radius:3px;background:var(--panel);font:12px/1.25 var(--mono);text-align:center;padding:7px 0;color:var(--muted)}
.cell small{font-size:9.5px;letter-spacing:-.02em}
.cell.u{background:var(--accent-soft);color:var(--accent);border-color:var(--accent)}
.cell.x{background:var(--bad-soft);color:var(--bad);border-color:var(--bad);font-weight:600}
.legend{font-size:14px;color:var(--muted);font-family:var(--mono)}
.chain{counter-reset:s;list-style:none;padding:0;display:flex;flex-direction:column;gap:10px}
.chain li{counter-increment:s;display:grid;grid-template-columns:2.2em 1fr;gap:8px}
.chain li::before{content:counter(s);font:600 14px/1.6 var(--mono);color:var(--accent)}
a{color:var(--accent)}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
@media (max-width:560px){body{font-size:16px}.cells{grid-template-columns:repeat(16,30px)}}

.wave{display:block;width:100%;height:auto;min-width:560px}
.figwrap{overflow-x:auto;border:1px solid var(--rule);border-radius:5px;background:var(--panel);padding:10px 8px}
.wave text{font-family:var(--mono)}
.wave .tick{font-size:10px;fill:var(--muted)}
.wave .lab{font-size:11.5px;fill:var(--fg)}
.wave .grid{stroke:var(--rule);stroke-width:1}
.wave .b0{fill:var(--bk0)} .wave .b1{fill:var(--bk1)} .wave .b2{fill:var(--bk2)} .wave .b3{fill:var(--bk3)}
.wave .ref{stroke:var(--refc);stroke-width:1.6}
.wave .bn{font-size:10px;fill:var(--fg);text-anchor:middle}
.wave .refn{fill:var(--refc);font-weight:600;font-size:12px}
.wave .coll{fill:var(--collc)}
.wave .w0{fill:var(--good-soft)} .wave .w1{fill:var(--bk2)} .wave .w2{fill:var(--collc)} .wave .w3{fill:var(--refc)}
.wave .arrow{fill:var(--fg)}
.wave .fetch{fill:var(--accent)} .wave .zero{stroke:var(--fg);stroke-width:1;stroke-dasharray:3 3}
.wave .l1ok{fill:var(--muted);opacity:.35} .wave .l1ref{fill:none;stroke:var(--refc);stroke-width:1.6}
.wave .box{fill:var(--panel);stroke:var(--fg);stroke-width:1.2}
.wave .boxt{font-size:12px;fill:var(--fg);text-anchor:middle}
.wave .boxs{font-size:10.5px;fill:var(--muted);text-anchor:middle}
.wave .wire{stroke:var(--muted);stroke-width:1;fill:none}
.legend2{display:flex;flex-wrap:wrap;gap:6px 14px;font:13px var(--mono);color:var(--muted);align-items:center}
.sw{display:inline-block;width:14px;height:12px;border-radius:2px;vertical-align:-2px;margin-right:4px;border:1px solid var(--rule)}
.wave .pause{fill:var(--bk2);stroke:var(--fg);stroke-width:.6;stroke-dasharray:2 2}
.wave .stair{fill:none;stroke:var(--good);stroke-width:2}
.wave .hl{fill:none;stroke:var(--accent);stroke-width:2;rx:3}
.wave .lead{stroke:var(--accent);stroke-width:1}
.wave .num{fill:var(--accent)} .wave .numt{font-size:11px;fill:var(--bg);text-anchor:middle;font-weight:600}

.wave .mp{fill:var(--refc)} .wave .emp{fill:var(--bk2)} .wave .acc{fill:var(--good)} .wave .blk{fill:var(--muted);opacity:.45}
.wave .okc{fill:var(--good)} .wave .refc{fill:var(--refc)}
.wave .ln0{fill:none;stroke:var(--good);stroke-width:2.2} .wave .ln1{fill:none;stroke:var(--refc);stroke-width:2.2}
.wave .ln0d{fill:var(--good)} .wave .ln1d{fill:var(--refc)}
.xstrip{width:100%;max-width:none;height:auto;display:block}
.xstrip .rd{fill:var(--good)} .xstrip .rf{fill:var(--refc)} .xstrip .id{fill:var(--code)}
.xstrip .lab,.xstrip .tick{font-family:var(--mono);font-size:10px;fill:var(--muted)} .xstrip .xx{font-size:9px;fill:var(--bg);font-family:var(--mono)}
.map td:first-child{white-space:nowrap}
.sym{display:inline-block;font:600 11.5px/1 var(--mono);padding:4px 7px;border-radius:3px;background:var(--accent-soft);color:var(--accent);white-space:nowrap}
nav.toc{display:flex;flex-wrap:wrap;gap:6px 16px;font:14px var(--mono)}
h4{font:600 17px/1.3 var(--display);margin:6px 0 0}
.wave .grant{fill:var(--good)} .wave .wait{fill:var(--refc)} .wave .l1{fill:var(--accent)} .wave .markbg{fill:var(--accent-soft)} .wave .base{stroke:var(--rule);stroke-width:1} .wave .lwrite{fill:var(--good);opacity:.6} .wave .lwait{fill:var(--refc)}
.sub{border-left:3px solid var(--rule);padding-left:16px;display:flex;flex-direction:column;gap:14px;min-width:0}
